238	// boundCheckDefinition resolves and verifies everything a check is bound
239	// to, in the required order: the version must exist and be frozen, its
240	// compiled artifact must exist, the supplied hash must equal that
241	// artifact's hash (artifacts of other names or versions never qualify), and
242	// the stored definition behind the artifact must be readable. It returns
243	// the canonical definition and the bound artifact hash.
244	//
245	// Callers must hold the store read lock.
246	func (s *Store) boundCheckDefinition(name string, version int, hash string) (*canonicalDefinition, string, error) {
247		circuit := findCircuit(s.data.Circuits, name, version)
248		if circuit == nil {
249			return nil, "", notFoundf("circuit %q version %d does not exist", name, version)
250		}
251		if !circuit.Frozen {
252			return nil, "", notFrozenf("circuit %q version %d must be frozen before inputs can be checked", name, version)
253		}
254		artifact := findArtifact(s.data.Artifacts, name, version)
255		if artifact == nil {
256			return nil, "", artifactMissingf("circuit %q version %d has no compiled artifact", name, version)
257		}
258		if artifact.Hash != hash {
259			return nil, "", artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
260				hash, name, version, artifact.Hash)
261		}
262		if circuit.Definition == nil {
263			return nil, "", corruptf("artifact for %q v%d exists but its definition is missing", name, version)
264		}
265		parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
266		if perr != nil {
267			return nil, "", corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
268		}
269		return parsed, artifact.Hash, nil
270	}
271	
272	// evaluateCheck runs the one shared verdict: the 1-based index of the first
273	// failing constraint, or zero when every constraint holds. The witness is
274	// already parsed into field residues by parseWitnessValues, so this performs
275	// no numeric conversion of its own.
276	func evaluateCheck(def *canonicalDefinition, witness parsedWitness, hash string) CheckResult {
277		failure := def.evaluate(witness)
278		return CheckResult{Satisfied: failure == 0, Hash: hash, FirstFailure: failure}
279	}
280	
281	// --- lookup / mapping helpers ---------------------------------------------
282	
283	func findArtifact(as []persistArtifact, name string, version int) *persistArtifact {
284		for i := range as {
285			if as[i].Name == name && as[i].Version == version {
286				return &as[i]
287			}
288		}
289		return nil
290	}
291	
292	func artifactFromPersist(a persistArtifact) Artifact {
293		return Artifact{
294			Name: a.Name, Version: a.Version,
295			Modulus: int(a.Modulus), Constraints: a.Constraints, Hash: a.Hash,
296		}
297	}
298	
299	func definitionMissingf(format string, args ...any) error {
300		return StoreError{Kind: ErrDefinitionMissing.Kind, Detail: fmt.Sprintf(format, args...)}
301	}
302	
303	func artifactMissingf(format string, args ...any) error {
304		return StoreError{Kind: ErrArtifactMissing.Kind, Detail: fmt.Sprintf(format, args...)}
305	}
306	
307	func artifactMismatchf(format string, args ...any) error {
308		return StoreError{Kind: ErrArtifactMismatch.Kind, Detail: fmt.Sprintf(format, args...)}
309	}
