447	// Both entry points run the same binding and verdict rules: the same
448	// frozen version, hash and legal inputs yield identical conclusions, and
449	// the same gating errors in the same order.
450	func TestCheckInputEntryPointsEquivalent(t *testing.T) {
451		s := openTestStore(t)
452		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
453		s.FreezeCircuit("c", 1)
454		a, _ := s.CompileCircuit("c", 1)
455	
456		docs := map[string]string{
457			"good":       `{"public":["2"],"private":["3"]}`,
458			"negative":   `{"public":["-5"],"private":["-4"]}`,
459			"huge":       `{"public":["7000000000000000000000002"],"private":["3"]}`,
460			"unsatisfy":  `{"public":["2"],"private":["4"]}`,
461			"badwitness": `{"public":["2"]}`,
462		}
463		for name, doc := range docs {
464			t.Run(name, func(t *testing.T) {
465				path := writeTempJSON(t, doc)
466				fileRes, fileErr := s.CheckInputFile("c", 1, a.Hash, path)
467				if name == "badwitness" {
468					if !errors.Is(fileErr, ErrInvalidInput) {
469						t.Fatalf("file entry: want input format error, got %v", fileErr)
470					}
471					// The JSON witness's strict grammar rejects the document
472					// before the shared layout rules run; the in-API witness
473					// instead supplies the arrays directly.
474					if _, err := s.CheckInput("c", 1, a.Hash, Witness{Public: []string{"2", "x"}, Private: []string{"3"}}); !errors.Is(err, ErrInvalidInput) {
475						t.Fatalf("in-API entry: want input format error, got %v", err)
