477					return
478				}
479				if fileErr != nil {
480					t.Fatalf("file entry: %v", fileErr)
481				}
482				w, werr := parseWitness([]byte(doc), 1, 1)
483				if werr != nil {
484					t.Fatal(werr)
485				}
486				directRes, err := s.CheckInput("c", 1, a.Hash, w)
487				if err != nil {
488					t.Fatalf("direct entry: %v", err)
489				}
490				if directRes != fileRes {
491					t.Fatalf("verdicts differ: direct=%+v file=%+v", directRes, fileRes)
492				}
493			})
494		}
495	
496		// Empty/nil slices are accepted for declared-zero groups through the
497		// direct entry; the JSON entry needs explicit arrays.
498		zero := `{"modulus":"7","constraints":[
499			{"a":[{"wire":0,"coeff":"1"}],"b":[{"wire":0,"coeff":"1"}],"c":[{"wire":0,"coeff":"1"}]}]}`
500		if _, err := s.CreateCircuit(Circuit{Name: "z", Version: 1, Constraints: 1, Description: "z"}); err != nil {
