668	func replaceFirst(haystack, marker, replacement []byte) []byte {
669		i := indexBytes(haystack, marker)
670		if i < 0 {
671			return haystack
672		}
673		out := append([]byte(nil), haystack[:i]...)
674		out = append(out, replacement...)
675		out = append(out, haystack[i+len(marker):]...)
676		return out
677	}
678	
679	func indexBytes(haystack, needle []byte) int {
680		for i := 0; i+len(needle) <= len(haystack); i++ {
681			if string(haystack[i:i+len(needle)]) == string(needle) {
682				return i
683			}
684		}
685		return -1
686	}
