		"--hash", hash, "--file", badPath); r.code != 0 ||
		!strings.Contains(r.out, "satisfied=false") || !strings.Contains(r.out, "first_failure=1") ||
		strings.Contains(r.out, "100003") || strings.Contains(r.err, "100003") {
		t.Fatalf("unsatisfied check: %+v", r)
	}

