		t.Fatalf("freeze: %+v", r)
	}
	if r := call("setup-record", "--dir", dir, "--name", "bare", "--version", "1"); r.code != 0 {
		t.Fatalf("setup: %+v", r)
	}
	if r := call("job-submit", "--dir", dir, "--id", "j1", "--name", "bare",
		"--version", "1"); r.code != 0 {
