1	package main
2	
3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"os"
8	
9		"github.com/asdhoaiqqq/zkcircuit-workbench/zkcircuit"
10	)
11	
12	// Process exit codes for the data commands.
13	const (
14		exitOK    = 0
15		exitRule  = 1 // business rule failure (not found, conflict, frozen, …)
16		exitUsage = 2 // bad command line
17		exitData  = 3 // storage cannot be read safely (corrupt/truncated/bad format)
18	)
19	
20	// dataCommands is the set of commands backed by a persistent data directory.
21	var dataCommands = map[string]bool{
22		"circuit-create":    true,
23		"circuit-update":    true,
24		"circuit-freeze":    true,
25		"circuit-copy":      true,
26		"circuit-get":       true,
27		"circuit-list":      true,
28		"setup-record":      true,
29		"setup-get":         true,
30		"job-submit":        true,
31		"job-get":           true,
32		"job-list":          true,
33		"constraint-import": true,
34		"circuit-compile":   true,
35		"input-check":       true,
36	}
37	
38	// dispatchDataCommand runs cmd with args. handled is false when cmd is not a
39	// data command, so the caller keeps the historical "unknown command" path.
40	func dispatchDataCommand(cmd string, args []string) (code int, handled bool) {
41		if !dataCommands[cmd] {
42			return exitUsage, false
43		}
44		return runDataCommand(cmd, args), true
45	}
46	
47	func runDataCommand(cmd string, args []string) int {
48		fs, f := newFlagSet(cmd, os.Stderr)
49		if err := fs.Parse(args); err != nil {
50			return exitUsage
51		}
52		// Record which value flags were explicitly provided, so circuit-update
53		// can distinguish "omitted" from "given a default value".
54		fs.Visit(func(fl *flag.Flag) {
55			switch fl.Name {
56			case "constraints":
57				f.constraintsSet = true
58			case "public-inputs":
59				f.publicInSet = true
60			case "private-inputs":
61				f.privateInSet = true
62			case "description":
63				f.descriptionSet = true
64			}
65		})
66		if len(fs.Args()) > 0 {
67			fmt.Fprintf(os.Stderr, "error: %s does not accept positional arguments (got %q)\n", cmd, fs.Args()[0])
68			return exitUsage
69		}
70		if f.dir == "" {
71			fmt.Fprintf(os.Stderr, "error: --dir is required for %s\n", cmd)
72			return exitUsage
73		}
74	
75		switch cmd {
76		case "circuit-create":
77			return cmdCircuitCreate(f)
78		case "circuit-update":
79			return cmdCircuitUpdate(f)
80		case "circuit-freeze":
81			return cmdCircuitFreeze(f)
82		case "circuit-copy":
83			return cmdCircuitCopy(f)
84		case "circuit-get":
85			return cmdCircuitGet(f)
86		case "circuit-list":
87			return cmdCircuitList(f)
88		case "setup-record":
89			return cmdSetupRecord(f)
90		case "setup-get":
91			return cmdSetupGet(f)
92		case "job-submit":
93			return cmdJobSubmit(f)
94		case "job-get":
95			return cmdJobGet(f)
96		case "job-list":
97			return cmdJobList(f)
98		case "constraint-import":
99			return cmdConstraintImport(f)
100		case "circuit-compile":
101			return cmdCircuitCompile(f)
102		case "input-check":
103			return cmdInputCheck(f)
104		}
105		return exitUsage
106	}
107	
108	func requireNameVersion(cmd string, f *cliFlags) (bool, int) {
109		if f.name == "" {
110			fmt.Fprintf(os.Stderr, "error: --name is required for %s\n", cmd)
111			return false, exitUsage
112		}
113		if f.version <= 0 {
114			fmt.Fprintf(os.Stderr, "error: --version must be a positive integer for %s\n", cmd)
115			return false, exitUsage
116		}
117		return true, exitOK
118	}
119	
120	func openStore(f *cliFlags) (*zkcircuit.Store, int) {
121		store, err := zkcircuit.Open(f.dir)
122		if err != nil {
123			return nil, reportStoreError(err)
124		}
125		return store, exitOK
126	}
127	
128	// reportStoreError prints a failed storage/domain call and returns the exit
129	// code. Rule failures are 1; unreadable data is 3.
130	func reportStoreError(err error) int {
131		if errors.Is(err, zkcircuit.ErrDataCorrupt) {
132			fmt.Fprintf(os.Stderr, "error: read failed: %v\n", err)
133			return exitData
134		}
135		var domainErr zkcircuit.StoreError
136		if errors.As(err, &domainErr) {
137			fmt.Fprintf(os.Stderr, "error: %v\n", err)
138			return exitRule
139		}
140		fmt.Fprintf(os.Stderr, "error: storage failure: %v\n", err)
141		return exitData
142	}
143	
144	func circuitFromFlags(f *cliFlags) zkcircuit.Circuit {
145		return zkcircuit.Circuit{
146			Name: f.name, Version: f.version,
147			Constraints: f.constraints, PublicInputs: f.publicIn, PrivateInputs: f.privateIn,
148			Description: f.description,
149		}
150	}
151	
152	func formatCircuit(c zkcircuit.Circuit) string {
153		return fmt.Sprintf("name=%s version=%d constraints=%d public_inputs=%d private_inputs=%d frozen=%t description=%q",
154			c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Frozen, c.Description)
155	}
156	
157	func formatJob(j zkcircuit.Job) string {
158		s := fmt.Sprintf("id=%s circuit=%s version=%d kind=%s attempt=%d", j.ID, j.Circuit, j.Version, j.Kind, j.Attempt)
159		if j.Artifact != "" {
160			s += " artifact=" + fmt.Sprintf("%q", j.Artifact)
161		}
162		if j.CompiledHash != "" {
163			s += " compiled_hash=" + j.CompiledHash
164		}
165		return s
166	}
167	
168	func cmdCircuitCreate(f *cliFlags) int {
169		if ok, code := requireNameVersion("circuit-create", f); !ok {
170			return code
171		}
172		store, code := openStore(f)
173		if store == nil {
174			return code
175		}
176		defer store.Close()
177	
178		c, err := store.CreateCircuit(circuitFromFlags(f))
179		if err != nil {
180			return reportStoreError(err)
181		}
182		fmt.Println("circuit version:", formatCircuit(c))
183		return exitOK
184	}
185	
186	func cmdCircuitUpdate(f *cliFlags) int {
187		if ok, code := requireNameVersion("circuit-update", f); !ok {
188			return code
