			if !errors.Is(err, ErrInvalidArgument) {
				t.Fatalf("want ErrInvalidArgument, got %v", err)
			}
			if _, gerr := s.GetDefinition("c", 1); !errors.Is(gerr, ErrDefinitionMissing) {
				t.Fatalf("rejected import left a definition: %v", gerr)
			}
		})
	}
